// social-admin — read + manage the X draft queue for the admin dashboard.
// Admin-key gated. GET returns the recent queue; POST mutates one row
// (approve | unapprove | skip | edit). Posting itself is social-post; drafts
// are generated by social-generate. No X calls happen here.

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SRK = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const ADMIN_KEY = Deno.env.get("VEIL_ADMIN_KEY") ?? "";

const cors = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, apikey, content-type, x-admin-key",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
};
const json = (b: unknown, status = 200) =>
  new Response(JSON.stringify(b), { status, headers: { ...cors, "Content-Type": "application/json" } });

async function sb(path: string, init: RequestInit = {}): Promise<Response> {
  return await fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
    ...init,
    headers: { apikey: SRK, Authorization: `Bearer ${SRK}`, "Content-Type": "application/json", ...(init.headers || {}) },
  });
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: cors });
  const url = new URL(req.url);
  const key = req.headers.get("x-admin-key") ?? url.searchParams.get("key") ?? "";
  if (!ADMIN_KEY || key !== ADMIN_KEY) return json({ error: "unauthorized" }, 401);

  if (req.method === "GET") {
    // Most-recent two issues' worth of drafts, newest week first.
    const r = await sb("social_posts?select=*&order=week_of.desc,position.asc&limit=24");
    if (!r.ok) return json({ error: "fetch_failed", detail: await r.text() }, 502);
    return json({ ok: true, queue: await r.json() });
  }

  // POST: mutate one row.
  let body: { action?: string; id?: string; text?: string } = {};
  try { body = await req.json(); } catch { /* empty */ }
  const { action, id, text } = body;
  if (!id || !action) return json({ error: "id_and_action_required" }, 400);

  let patch: Record<string, unknown> | null = null;
  if (action === "approve") patch = { status: "approved" };
  else if (action === "unapprove") patch = { status: "draft" };
  else if (action === "skip") patch = { status: "skipped" };
  else if (action === "edit") {
    if (typeof text !== "string" || !text.trim()) return json({ error: "text_required" }, 400);
    patch = { text: text.slice(0, 500) };
  } else return json({ error: "bad_action" }, 400);

  // Never let the dashboard flip a row that's already posted.
  const r = await sb(`social_posts?id=eq.${id}&status=neq.posted`, {
    method: "PATCH",
    headers: { Prefer: "return=representation" },
    body: JSON.stringify(patch),
  });
  if (!r.ok) return json({ error: "update_failed", detail: await r.text() }, 502);
  const rows = await r.json();
  if (!Array.isArray(rows) || !rows.length) return json({ error: "not_found_or_posted" }, 404);
  return json({ ok: true, row: rows[0] });
});
